pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MyContract c;

    function setUp() public {
        c = new MyContract();
    }

    function _run(uint256 a1, uint256 a2) internal {
        a1 = bound(a1, 0, 1);
        vm.assume(a2 > 1 ether);
        vm.assume(address(c).balance >= a2);
        bool r1;
        try c.sendTo(address(this), a1) { r1 = false; } catch { r1 = true; }
        bool r2;
        try c.sendTo(address(this), a2) { r2 = false; } catch { r2 = true; }
        assertTrue(r1 == r2);
    }

    function testFuzz_run(uint256 a1, uint256 a2) public {
        _run(a1, a2);
    }

    receive() external payable {}
}
